"use client";

import * as React from "react";

type Props = {
  enabled?: boolean;
  children: React.ReactNode;
};

export function MoneytreesThemeProvider({ enabled = true, children }: Props) {
  React.useEffect(() => {
    if (typeof document === "undefined") return;
    const el = document.documentElement;
    if (enabled) {
      el.setAttribute("data-theme", "moneytrees");
      return () => {
        if (el.getAttribute("data-theme") === "moneytrees") {
          el.removeAttribute("data-theme");
        }
      };
    }
  }, [enabled]);

  return <>{children}</>;
}
